import{_ as a,o,c as t,a2 as i}from"./chunks/framework.x7b91k6X.js";const g=JSON.parse('{"title":"漫画 · 第 13 话 国际化与无障碍","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.13-i18n-a11y.md","filePath":"comics/EP.13-i18n-a11y.md","lastUpdated":1792677465000}'),r={name:"comics/EP.13-i18n-a11y.md"};function l(n,e,c,d,s,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-13-话-国际化与无障碍" tabindex="-1">漫画 · 第 13 话 国际化与无障碍 <a class="header-anchor" href="#漫画-·-第-13-话-国际化与无障碍" aria-label="Permalink to &quot;漫画 · 第 13 话 国际化与无障碍&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../13-i18n-a11y">13-i18n-a11y.md</a> ｜ 原画：<a href="./EP.13-i18n-a11y.svg">EP.13-i18n-a11y.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：<code>Text(&quot;确认下单&quot;)</code> 硬编码中文，海外用户看不懂；按钮没加无障碍标签，视障用户用 VoiceOver 读不出。</li><li><strong>Runtime 长老</strong>：教她用 String Catalog 管多语言、用无障碍四层模型适配读屏。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>国际化（i18n）和无障碍（a11y）不是上线后打的补丁，是从第一行代码就要做的基建。Xcode 15 的 String Catalog 自动收集代码里的字符串，集中翻译；CLDR 复数规则处理不同语言的单复数变形；无障碍四层模型（语义/标签/值/特征）让 VoiceOver 能读懂界面。CI 跑伪本地化提前发现硬编码和布局溢出。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><ul><li><strong>硬编码文本</strong>：<code>Text(&quot;确认下单&quot;)</code> 写死中文，海外用户看到的是中文界面，只能靠猜；</li><li><strong>无障碍缺失</strong>：自定义按钮没加 <code>accessibilityLabel</code>，VoiceOver 读成「按钮」而不是「确认下单按钮」，视障用户无法操作。</li></ul><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><ul><li><strong>String Catalog</strong>：Xcode 15+ 引入，自动扫描代码中的 <code>Text(&quot;key&quot;)</code>、<code>NSLocalizedString</code> 等，生成 <code>.xcstrings</code> 文件，多语言翻译集中管理，不再需要手动维护 <code>.strings</code> 文件。</li><li><strong>CLDR 复数规则</strong>：不同语言单复数规则不同。英语只有 1 和 other 两种，俄语有 1（1,21,31…）、few（2-4,22-24…）、many（5-20,25-30…）三套。用 <code>String(localized: &quot;items.count \\(count)&quot;)</code> 让系统自动选正确形式。</li><li><strong>无障碍四层模型</strong>：①语义（是什么，按钮/链接/标题）②标签（叫什么，「确认下单」）③值（当前状态，开关「开/关」）④特征（可做什么，可调/可选中）。</li><li><strong>伪本地化</strong>：把字符串替换成带变音符号的伪译文（如 <code>[öóñfirm órdér]</code>），不真正翻译但能立刻发现硬编码和布局溢出。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><ol><li><strong>字符串全走 Localized</strong>：所有用户可见文本用 <code>String(localized:)</code> 或 <code>Text(&quot;key&quot;, bundle: .module)</code>，禁止硬编码；</li><li><strong>加 a11y 标签</strong>：<code>.accessibilityLabel()</code> 给读屏软件提供语义化名称，<code>.accessibilityValue()</code> 提供动态值；</li><li><strong>CI 跑伪本地化</strong>：构建一个伪本地化版本，自动检查是否有硬编码字符串和布局溢出。</li></ol><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>字符串全走 String Catalog，禁止硬编码，多语言集中翻译不散落。</li><li>无障碍四层：语义/标签/值/特征，读屏软件靠这些理解界面。</li><li>CI 跑伪本地化，提前发现硬编码和长文本布局溢出。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么「确认下单」四个字，英文可能变成 15 个字符，布局会出问题？</p><p><strong>答</strong>：翻译后文本长度变化是国际化最常见的坑。中文「确认下单」4 个字，英文 &quot;Confirm Order&quot; 12 字符，德文 &quot;Bestellung bestätigen&quot; 21 字符。如果按钮宽度是按中文 4 个字定的固定宽度，英文就会被截断或换行。解法是：①用自适应布局（不用固定宽度，用 leading/trailing 约束）；②CI 跑伪本地化提前发现溢出；③为长文本语言单独调布局。这就是为什么国际化要和布局设计一起做。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>运行 <code>swift run LocalizationA11y</code>，查看 <code>CLDRPluralRules.swift</code>（复数规则）、<code>PseudoLocalizer.swift</code>（伪本地化）和 <code>ContrastAuditor.swift</code>（对比度审计）的实现；阅读第 13 章的 String Catalog 使用教程和 WCAG 2.2 合规矩阵。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>App 本身完善了，可锁屏 Widget 不刷新、Siri 喊不出指令、通知内容是密文。第 14 话《系统触点：Widget 与 App Intents》，让 App 融入整个系统生态。</p>',22)])])}const q=a(r,[["render",l]]);export{g as __pageData,q as default};
